package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"sync"
	"time"
)

type Role int

const (
	RoleUser Role = iota
	RoleAdmin
	RoleAuditor
)

type User struct {
	ID       string
	Username string
	Role     Role
	Balance  int64
}

type PaymentRequest struct {
	FromID string
	ToID   string
	Amount int64
}

type PaymentLedger struct {
	mu       sync.RWMutex
	users    map[string]*User
	pending  map[string]*PaymentRequest
	approved map[string]bool
}

func NewPaymentLedger() *PaymentLedger {
	return &PaymentLedger{
		users:    make(map[string]*User),
		pending:  make(map[string]*PaymentRequest),
		approved: make(map[string]bool),
	}
}

func generateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func (pl *PaymentLedger) RegisterUser(username string, role Role) string {
	pl.mu.Lock()
	defer pl.mu.Unlock()
	id := generateID()
	pl.users[id] = &User{ID: id, Username: username, Role: role, Balance: 10000}
	return id
}

// SubmitPayment creates a pending payment that requires admin approval
func (pl *PaymentLedger) SubmitPayment(requesterID, fromID, toID string, amount int64) (string, error) {
	pl.mu.RLock()
	requester, exists := pl.users[requesterID]
	pl.mu.RUnlock()

	if !exists {
		return "", fmt.Errorf("requester not found")
	}

	// Only users or admins can submit payments
	if requester.Role == RoleAuditor {
		return "", fmt.Errorf("auditors cannot submit payments")
	}

	pl.mu.Lock()
	defer pl.mu.Unlock()

	from, fromExists := pl.users[fromID]
	_, toExists := pl.users[toID]

	if !fromExists || !toExists {
		return "", fmt.Errorf("user not found")
	}

	if from.Balance < amount {
		return "", fmt.Errorf("insufficient balance")
	}

	if amount <= 0 {
		return "", fmt.Errorf("invalid amount")
	}

	paymentID := generateID()
	pl.pending[paymentID] = &PaymentRequest{FromID: fromID, ToID: toID, Amount: amount}
	return paymentID, nil
}

// ApprovePayment - admin approves a pending payment
func (pl *PaymentLedger) ApprovePayment(approverID, paymentID string) error {
	pl.mu.RLock()
	approver, exists := pl.users[approverID]
	pl.mu.RUnlock()

	if !exists {
		return fmt.Errorf("approver not found")
	}

	if approver.Role != RoleAdmin {
		return fmt.Errorf("only admins can approve payments")
	}

	// Mark as approved - separate from execution for audit trail
	pl.mu.Lock()
	_, pendingExists := pl.pending[paymentID]
	if !pendingExists {
		pl.mu.Unlock()
		return fmt.Errorf("payment not found")
	}
	pl.approved[paymentID] = true
	pl.mu.Unlock()

	return nil
}

// ExecutePayment - processes an approved payment
func (pl *PaymentLedger) ExecutePayment(executorID, paymentID string) error {
	pl.mu.RLock()
	executor, exists := pl.users[executorID]
	pl.mu.RUnlock()

	if !exists {
		return fmt.Errorf("executor not found")
	}

	if executor.Role != RoleAdmin && executor.Role != RoleUser {
		return fmt.Errorf("insufficient permissions")
	}

	// Check approval status
	pl.mu.RLock()
	isApproved := pl.approved[paymentID]
	pl.mu.RUnlock()

	if !isApproved {
		return fmt.Errorf("payment not approved")
	}

	// Execute the transfer
	pl.mu.Lock()
	defer pl.mu.Unlock()

	payment, exists := pl.pending[paymentID]
	if !exists {
		return fmt.Errorf("payment not found")
	}

	from := pl.users[payment.FromID]
	to := pl.users[payment.ToID]

	if from.Balance < payment.Amount {
		return fmt.Errorf("insufficient balance at execution time")
	}

	from.Balance -= payment.Amount
	to.Balance += payment.Amount

	// Remove from pending but keep approval record
	delete(pl.pending, paymentID)

	return nil
}

func main() {
	ledger := NewPaymentLedger()

	adminID := ledger.RegisterUser("admin", RoleAdmin)
	userA := ledger.RegisterUser("alice", RoleUser)
	userB := ledger.RegisterUser("bob", RoleUser)

	http.HandleFunc("/submit", func(w http.ResponseWriter, r *http.Request) {
		paymentID, err := ledger.SubmitPayment(r.Header.Get("X-User-ID"), userA, userB, 500)
		if err != nil {
			http.Error(w, err.Error(), 400)
			return
		}
		fmt.Fprintf(w, "Payment submitted: %s", paymentID)
	})

	http.HandleFunc("/approve", func(w http.ResponseWriter, r *http.Request) {
		err := ledger.ApprovePayment(adminID, r.URL.Query().Get("id"))
		if err != nil {
			http.Error(w, err.Error(), 400)
			return
		}
		fmt.Fprintf(w, "Payment approved")
	})

	http.HandleFunc("/execute", func(w http.ResponseWriter, r *http.Request) {
		err := ledger.ExecutePayment(r.Header.Get("X-User-ID"), r.URL.Query().Get("id"))
		if err != nil {
			http.Error(w, err.Error(), 400)
			return
		}
		fmt.Fprintf(w, "Payment executed")
	})

	_ = adminID
	_ = userA
	_ = userB
	_ = time.Now()

	http.ListenAndServe(":8080", nil)
}
